// Config plugin: faster local Android builds (Phase 0.5, D-015).
// android/ is generated by `expo prebuild`, so Gradle settings must be applied here
// to survive `prebuild --clean`. Only affects build tooling, not the app itself.
const { withGradleProperties } = require("expo/config-plugins");

const PROPERTIES = {
  // Template default is -Xmx2048m; more heap = less GC during Kotlin/C++/dex steps.
  "org.gradle.jvmargs": "-Xmx6g -XX:MaxMetaspaceSize=1g -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8",
  // Reuse task outputs across clean builds / prebuild --clean (stored in ~/.gradle/caches/build-cache-1).
  "org.gradle.caching": "true",
};

module.exports = function withAndroidBuildSpeed(config) {
  return withGradleProperties(config, (cfg) => {
    for (const [key, value] of Object.entries(PROPERTIES)) {
      const existing = cfg.modResults.find((item) => item.type === "property" && item.key === key);
      if (existing) {
        existing.value = value;
      } else {
        cfg.modResults.push({ type: "property", key, value });
      }
    }
    return cfg;
  });
};
